import{_ as t,a,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Delete a GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-gdpr-request","title":"Delete a GDPR Request","description":"Remove a GDPR data request record owned by the authenticated customer.","request":"DELETE /api/shop/gdpr-requests/12\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 204 No Content\\n","commonErrors":[{"error":"400 Bad Request","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before deleting a request"},{"error":"404 Not Found","cause":"The request does not exist or is not owned by the authenticated customer","solution":"Only request IDs belonging to the logged-in customer can be deleted"},{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/gdpr-requests/delete-gdpr-request.md","filePath":"api/rest-api/shop/gdpr-requests/delete-gdpr-request.md","lastUpdated":1786429091000}`),o={name:"api/rest-api/shop/gdpr-requests/delete-gdpr-request.md"};function d(n,e,i,u,h,l){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="delete-a-gdpr-request" tabindex="-1">Delete a GDPR Request <a class="header-anchor" href="#delete-a-gdpr-request" aria-label="Permalink to &quot;Delete a GDPR Request&quot;">​</a></h1><p>Remove a GDPR data request record owned by the authenticated customer. On success the endpoint returns <strong>HTTP 204 No Content</strong> with an empty body. A customer can only delete their own requests.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/shop/gdpr-requests/{id}</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the endpoint returns <strong>HTTP 400</strong> with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> The feature has been turned off on the admin side.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The request ID to delete.</td></tr></tbody></table><h2 id="response-204-no-content" tabindex="-1">Response (204 No Content) <a class="header-anchor" href="#response-204-no-content" aria-label="Permalink to &quot;Response (204 No Content)&quot;">​</a></h2><p>A successful delete returns HTTP 204 with no response body.</p><h2 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>204 No Content</code></td><td>Request deleted.</td></tr><tr><td><code>400 Bad Request</code></td><td>GDPR is disabled in the store&#39;s admin configuration.</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid storefront key.</td></tr><tr><td><code>403 Forbidden</code></td><td>Missing or invalid customer Bearer token.</td></tr><tr><td><code>404 Not Found</code></td><td>The request does not exist or is not owned by the customer.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">Raise a GDPR Request</a> — raise a delete or update request</li><li><a href="/api/rest-api/shop/gdpr-requests/revoke-gdpr-request.html">Revoke a GDPR Request</a> — withdraw a request still being processed</li><li><a href="/api/rest-api/shop/gdpr-requests/">GDPR Requests Overview</a> — the GDPR menu overview, including the setting that gates it</li></ul>',18)]))}const q=t(o,[["render",d]]);export{p as __pageData,q as default};
